/*
 * The WebD3D8_* entry points of the original library as real functions (generated by tools/gen_webd3d8_compat.py, do
 * not edit): link compatibility for code that declares them itself instead of including <WebD3D8/WebD3D8.h>, for example
 *
 *     extern "C" void *WebD3D8_LookupProc(const char *name) __attribute__((weak));
 *
 * in a Win32 compatibility layer. The object is always linked together with the library (see CMakeLists.txt) so that such
 * weak references resolve.
 */
#include <dxwebgl2/dxwebgl2.h>

extern "C" {

void WebD3D8_SetCanvas(const char *selector)
{
    dxwebgl2_SetCanvas(selector);
}

void WebD3D8_SetDesktopSize(unsigned width, unsigned height)
{
    dxwebgl2_SetDesktopSize(width, height);
}

void WebD3D8_SetShaderModel(unsigned vertexShaderVersion, unsigned pixelShaderVersion)
{
    dxwebgl2_SetShaderModel(vertexShaderVersion, pixelShaderVersion);
}

void WebD3D8_SetPresentMode(int mode)
{
    dxwebgl2_SetPresentMode(mode);
}

void WebD3D8_SetPlatformHooks(const dxwebgl2_PlatformHooks *hooks)
{
    dxwebgl2_SetPlatformHooks(hooks);
}

void WebD3D8_SetContextProxy(int mode)
{
    dxwebgl2_SetContextProxy(mode);
}

void WebD3D8_SetDebug(int flags)
{
    dxwebgl2_SetDebug(flags);
}

void WebD3D8_SetReleaseTextureShadows(int enable)
{
    dxwebgl2_SetReleaseTextureShadows(enable);
}

void WebD3D8_SetDisableS3TC(int disable)
{
    dxwebgl2_SetDisableS3TC(disable);
}

void WebD3D8_GetStats(dxwebgl2_Stats *out)
{
    dxwebgl2_GetStats(out);
}

void WebD3D8_SetReport(int seconds)
{
    dxwebgl2_SetReport(seconds);
}

void WebD3D8_PrintReport(void)
{
    dxwebgl2_PrintReport();
}

void WebD3D8_LoseContextAfterFrames(int frames, int restoreAfterFrames)
{
    dxwebgl2_LoseContextAfterFrames(frames, restoreAfterFrames);
}

void WebD3D8_LoseContextNow(int restoreAfterFrames)
{
    dxwebgl2_LoseContextNow(restoreAfterFrames);
}

void WebD3D8_SetFeatureOverrides(int disabledMask)
{
    dxwebgl2_SetFeatureOverrides(disabledMask);
}

unsigned WebD3D8_GetHitCount(const char *substring)
{
    return dxwebgl2_GetHitCount(substring);
}

void WebD3D8_ParseArguments(int argc, char **argv)
{
    dxwebgl2_ParseArguments(argc, argv);
}

void *WebD3D8_LookupProc(const char *name)
{
    return dxwebgl2_LookupProc(name);
}

const char *WebD3D8_GetRendererString(void)
{
    return dxwebgl2_GetRendererString();
}

} // extern "C"
